css:
.sl-footer-cta { font-family: var(--smartlearn-body-font, inherit); }
.sl-footer-cta .sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-footer-cta .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-footer-cta.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-footer-cta .sl-border { border-color: var(--smartlearn-card-border) !important; }

.sl-footer-cta .sl-cta-banner {
    padding-block: clamp(3.5rem, 7vw, 6rem);
    border-radius: 0 0 40px 40px;
    background-color: var(--smartlearn-btn-bg);
    background: linear-gradient(135deg, var(--smartlearn-btn-bg) 0%, color-mix(in srgb, var(--smartlearn-btn-bg) 82%, #000000) 100%);
}
.sl-footer-cta .sl-cta-title {
    color: var(--smartlearn-btn-text, #ffffff);
}
.sl-footer-cta .sl-cta-subtitle {
    max-width: 600px;
    color: var(--smartlearn-btn-text, #ffffff);
    opacity: 0.92;
}
.sl-footer-cta .sl-cta-overlay {
    background: radial-gradient(circle at top right, rgba(255,255,255,0.1), transparent 60%);
    pointer-events: none;
}
.sl-footer-cta .sl-btn-cta {
    background-color: var(--smartlearn-bg) !important;
    color: var(--smartlearn-text) !important;
    border: 2px solid transparent !important;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.sl-footer-cta .sl-btn-cta:hover,
.sl-footer-cta .sl-btn-cta:focus-visible {
    transform: scale(1.04);
    background-color: var(--smartlearn-card-bg) !important;
    color: var(--smartlearn-text) !important;
}
.sl-footer-cta .sl-btn-cta:focus-visible {
    outline: 2px solid var(--smartlearn-btn-text, #ffffff);
    outline-offset: 3px;
}
.sl-footer-cta .sl-footer-nav-link,
.sl-footer-cta .sl-footer-link {
    transition: color 0.2s ease;
}
.sl-footer-cta .sl-footer-nav-link:hover,
.sl-footer-cta .sl-footer-nav-link:focus-visible,
.sl-footer-cta .sl-footer-link:hover,
.sl-footer-cta .sl-footer-link:focus-visible {
    color: var(--smartlearn-primary) !important;
    text-decoration: underline !important;
}
.sl-footer-cta .sl-social-target {
    min-width: 40px;
    min-height: 40px;
}
.sl-footer-cta a:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
@media (max-width: 768px) {
    .sl-footer-cta .sl-cta-banner { border-radius: 0 0 20px 20px; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-footer-cta .sl-btn-cta,
    .sl-footer-cta .sl-footer-nav-link,
    .sl-footer-cta .sl-footer-link { transition: none; }
    .sl-footer-cta .sl-btn-cta:hover,
    .sl-footer-cta .sl-btn-cta:focus-visible { transform: none; }
}
